children.definitions:
open Filter

def TriangleFree {α : Type*} (G : SimpleGraph α) : Prop :=
  ∀ a b c : α, ¬ (G.Adj a b ∧ G.Adj b c ∧ G.Adj c a)

noncomputable def f (n : ℕ) : ℕ :=
  sSup {k : ℕ | ∃ (G : SimpleGraph (Fin n)), TriangleFree G ∧ k = G.chromaticNumber}

